import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

type Product = {
  name: string;
  price: number;
  description: string;
  img: string;
  link?: string;
};

const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch('http://localhost:4000/products')
      .then(res => res.json())
      .then(data => {
        setProducts(data);
        setLoading(false);
      })
      .catch(() => {
        setError('Failed to load products');
        setLoading(false);
      });
  }, []);

  return (
    <div style={{ maxWidth: 1200, margin: '0 auto', padding: '32px 8px', fontFamily: 'Inter, Arial, Helvetica, sans-serif' }}>
      {/* Responsive styles for mobile */}
      <style>{`
        .products-grid {
          display: grid;
          grid-template-columns: 1fr;
          gap: 32px;
          justify-items: center;
          margin-left: auto;
          margin-right: auto;
          width: 100%;
        }
        @media (min-width: 900px) {
          .products-grid {
            grid-template-columns: 1fr 1fr;
            max-width: 1340px;
          }
        }
        @media (min-width: 900px) {
          .products-grid {
            grid-template-columns: 1fr 1fr;
          }
          .product-card {
            max-width: 640px;
            width: 100%;
            margin: 0 0 32px 0 !important;
          }
        }
        @media (max-width: 899px) {
          .products-grid {
            grid-template-columns: 1fr;
          }
          .product-card {
            max-width: 100% !important;
            margin: 0 auto 32px auto !important;
          }
        }
        @media (min-width: 900px) {
          .products-grid {
            grid-template-columns: repeat(2, 1fr);
            max-width: 1340px;
            place-content: center;
          }
          .product-card {
            max-width: 600px;
            width: 100%;
            margin: 0 0 32px 0 !important;
          }
        }
          }
          .product-title {
            font-size: 20px !important;
          }
          .product-desc {
            font-size: 15px !important;
          }
          .product-price {
            font-size: 16px !important;
          }
          .product-btn {
            font-size: 16px !important;
            padding: 12px 0 !important;
          }
        }
        @media (max-width: 400px), (max-width: 375px) and (max-height: 667px) {
          .product-card {
            padding: 4px !important;
            border-radius: 10px !important;
          }
          .product-img {
            width: 94vw !important;
            max-width: 94vw !important;
            margin-bottom: 10px !important;
          }
          .product-title {
            font-size: 17px !important;
            margin-bottom: 8px !important;
          }
          .product-desc {
            font-size: 13px !important;
            margin-bottom: 10px !important;
          }
          .product-price {
            font-size: 14px !important;
            margin-bottom: 8px !important;
          }
          .product-btn {
            font-size: 14px !important;
            padding: 10px 0 !important;
            border-radius: 8px !important;
          }
        }
      `}</style>
      <h1 style={{ textAlign: 'center', marginBottom: 32, fontFamily: 'Inter, Arial, Helvetica, sans-serif' }}>
        <span>SUPERCHARGE YOUR </span>
        <span style={{ background: '#fff200', color: '#222', padding: '0 4px', borderRadius: 4 }}>HEALTH</span>
      </h1>
      {loading ? (
        <div style={{ textAlign: 'center', marginTop: 32 }}>Loading products...</div>
      ) : error ? (
        <div style={{ textAlign: 'center', color: 'red', marginTop: 32 }}>{error}</div>
      ) : (
        <div className="products-grid" style={{ width: '100%', maxWidth: 900, margin: '0 auto' }}>
          {products.map((p, idx) => (
            <div
              key={idx}
              className="product-card"
              style={{ background: '#fff', borderRadius: 16, boxShadow: '0 2px 8px #eee', maxWidth: 640, width: '100%', padding: 16, margin: '0 auto 32px auto', display: 'flex', flexDirection: 'column', alignItems: 'center' }}
            >
              <img
                className="product-img"
                src={p.img.startsWith('http') ? p.img : `http://localhost:4000${p.img}`}
                alt={p.name}
                style={{ width: 600, height: 420, objectFit: 'contain', marginBottom: 24, maxWidth: '100%' }}
              />
              <h3 className="product-title" style={{ fontWeight: 700, marginBottom: 12, fontSize: 28 }}>{p.name}</h3>
              <p className="product-desc" style={{ fontSize: 18, color: '#222', marginBottom: 20, textAlign: 'center' }}>{p.description}</p>
              <div className="product-price" style={{ fontWeight: 700, marginBottom: 12, fontSize: 20 }}>
                USD ${p.price.toFixed(2)} <span style={{ fontWeight: 400, fontSize: 14 }}>Retail</span>
              </div>
              <label style={{ marginBottom: 12, fontSize: 16 }}>
                <input type="checkbox" style={{ marginRight: 8 }} /> Subscribe & save 25%
              </label>
              <button
                className="product-btn"
                style={{ width: '100%', padding: '16px 0', borderRadius: 10, border: '1.5px solid #222', background: '#fff', fontWeight: 700, fontSize: 20, cursor: 'pointer', marginTop: 8 }}
                onClick={() => { if (p.link) window.open(p.link, '_blank'); }}
                disabled={!p.link}
              >
                Add to Cart +
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Home;
